@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-chart__table { width: 100%; min-width: 0; height: var(--whatiuse-chart-height, 264px); overflow: auto; border-radius: var(--whatiuse-radius-container); background: var(--whatiuse-bg-stage); }

.whatiuse-chart__table--visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }

.whatiuse-chart__table table { width: 100%; border-collapse: collapse; font-size: var(--whatiuse-type-metadata); font-variant-numeric: tabular-nums; }

.whatiuse-chart__table caption { padding: 10px 12px; text-align: left; color: var(--whatiuse-fg-default); font-weight: 590; }

.whatiuse-chart__table th,
.whatiuse-chart__table td { padding: 8px 12px; border-top: 1px solid var(--whatiuse-separator); text-align: right; white-space: nowrap; }

.whatiuse-chart__table th:first-child { text-align: left; }

.whatiuse-chart__table thead th { color: var(--whatiuse-fg-subtle); font-weight: 540; }

.whatiuse-chart__table tbody th { color: var(--whatiuse-fg-muted); font-weight: 520; }

.whatiuse-donut-chart { display: grid; width: 100%; min-width: 0; margin: 0; gap: 12px; }

.whatiuse-donut-chart__header { display: flex; min-width: 0; align-items: flex-start; justify-content: space-between; gap: 20px; }

.whatiuse-donut-chart__header > div { display: grid; min-width: 0; gap: 3px; }

.whatiuse-donut-chart__header h3 { margin: 0; color: var(--whatiuse-fg-default); font-size: var(--whatiuse-type-section); font-weight: 610; letter-spacing: -.022em; }

.whatiuse-donut-chart__header p { margin: 0; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-metadata); line-height: 1.45; }

.whatiuse-donut-chart__data-toggle { min-height: 28px; flex: none; padding: 0 8px; border: 0; border-radius: var(--whatiuse-radius-control); background: transparent; color: var(--whatiuse-fg-muted); font: inherit; font-size: var(--whatiuse-type-metadata); cursor: pointer; transition: background-color var(--whatiuse-hover-duration) var(--whatiuse-ease), color var(--whatiuse-hover-duration) var(--whatiuse-ease); }

.whatiuse-donut-chart__stage { position: relative; min-width: 0; min-height: 264px; }

.whatiuse-donut-chart__stage > [hidden] { display: none; }

.whatiuse-donut-chart__stage > .whatiuse-chart__table { height: 264px; }

.whatiuse-donut-chart__content { display: grid; min-width: 0; grid-template-columns: minmax(190px, .92fr) minmax(170px, 1.08fr); align-items: center; gap: 18px; min-height: 264px; padding: 14px; border-radius: var(--whatiuse-radius-container); background: color-mix(in srgb, var(--whatiuse-bg-stage) 76%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--whatiuse-fg-default) 7%, transparent); }

.whatiuse-donut-chart__plot { position: relative; display: grid; width: 100%; max-width: 240px; aspect-ratio: 1; place-items: center; justify-self: center; border-radius: 50%; }

.whatiuse-donut-chart__plot:focus { outline: 0; }

.whatiuse-donut-chart__plot:focus-visible { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--whatiuse-focus-control) 34%, transparent); }

.whatiuse-donut-chart__plot svg { display: block; width: 100%; height: 100%; overflow: visible; transform: rotate(-90deg); }

.whatiuse-donut-chart__track { fill: none; stroke: color-mix(in srgb, var(--whatiuse-fg-default) 6%, transparent); stroke-width: 18; }

.whatiuse-donut-chart__segment { fill: none; stroke: var(--whatiuse-fg-default); stroke-linecap: round; stroke-width: 18; cursor: pointer; transition: opacity var(--whatiuse-hover-duration) var(--whatiuse-ease); }

.whatiuse-donut-chart__segment[data-tone="secondary"] { opacity: .62; }

.whatiuse-donut-chart__segment[data-tone="tertiary"] { opacity: .36; }

.whatiuse-donut-chart__segment[data-muted] { opacity: .16; }

.whatiuse-donut-chart__segment[data-active] { opacity: 1; }

.whatiuse-donut-chart__center { position: absolute; display: grid; max-width: 110px; place-items: center; gap: 3px; text-align: center; pointer-events: none; }

.whatiuse-donut-chart__center strong { overflow: hidden; max-width: 100%; color: var(--whatiuse-fg-default); font-size: 22px; font-variant-numeric: tabular-nums; font-weight: 620; letter-spacing: -.03em; text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-donut-chart__center span { overflow: hidden; max-width: 100%; color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-donut-chart__legend { display: grid; min-width: 0; gap: 2px; }

.whatiuse-donut-chart__legend button { display: grid; width: 100%; min-height: 38px; grid-template-columns: 7px minmax(0, 1fr) auto 44px; align-items: center; gap: 8px; padding: 5px 7px; border: 0; border-radius: var(--whatiuse-radius-control); background: transparent; color: var(--whatiuse-fg-muted); font: inherit; font-size: var(--whatiuse-type-ui); text-align: left; cursor: pointer; transition: background-color var(--whatiuse-hover-duration) var(--whatiuse-ease), color var(--whatiuse-hover-duration) var(--whatiuse-ease); }

.whatiuse-donut-chart__legend button[aria-pressed="true"] { background: var(--whatiuse-selected); color: var(--whatiuse-fg-default); }

.whatiuse-donut-chart__legend i { width: 7px; height: 7px; border-radius: 50%; background: var(--whatiuse-fg-default); }

.whatiuse-donut-chart__legend button[data-tone="secondary"] i { opacity: .62; }

.whatiuse-donut-chart__legend button[data-tone="tertiary"] i { opacity: .36; }

.whatiuse-donut-chart__legend span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-donut-chart__legend strong,
.whatiuse-donut-chart__legend small { font-variant-numeric: tabular-nums; text-align: right; }

.whatiuse-donut-chart__legend strong { color: var(--whatiuse-fg-default); font-weight: 570; }

.whatiuse-donut-chart__legend small { color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); }

.whatiuse-donut-chart__state { position: absolute; inset: 0; display: grid; place-content: center; color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-ui); text-align: center; }

.whatiuse-donut-chart__state[role="status"] { grid-auto-flow: column; align-items: center; gap: 8px; }

.whatiuse-donut-chart__state > span { width: 12px; height: 12px; border: 1.5px solid var(--whatiuse-separator-strong); border-top-color: var(--whatiuse-fg-default); border-radius: 50%; animation: whatiuse-spinner .7s linear infinite; }

.whatiuse-donut-chart__state--error { color: var(--whatiuse-fg-danger); }

.whatiuse-donut-chart__data-toggle:focus,
.whatiuse-donut-chart__legend button:focus { outline: 0; }

.whatiuse-donut-chart__data-toggle:focus-visible,
.whatiuse-donut-chart__legend button:focus-visible {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--whatiuse-focus-control) 42%, transparent);
}

@media (hover: hover) and (pointer: fine) {
.whatiuse-donut-chart__data-toggle:hover,
.whatiuse-donut-chart__legend button:hover { background: var(--whatiuse-hover); color: var(--whatiuse-fg-default); }
}

.whatiuse-donut-chart__data-toggle:active,
.whatiuse-donut-chart__legend button:active { transform: scale(.985); }

@media (max-width: 640px) {
.whatiuse-donut-chart__content { grid-template-columns: 1fr; }

.whatiuse-donut-chart__plot { max-width: 220px; }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-donut-chart__state > span { animation: none; }

.whatiuse-donut-chart__segment { transition-duration: 0ms; }
}

.whatiuse-donut-chart { gap: 9px; }

.whatiuse-donut-chart__header { align-items: center; }

.whatiuse-donut-chart__header h3 {
    font-size: var(--whatiuse-type-ui);
    font-weight: 600;
    letter-spacing: -.014em;
  }

.whatiuse-donut-chart__header p { line-height: 1.35; }

.whatiuse-donut-chart__data-toggle {
    min-height: 26px;
    padding-inline: 6px;
  }

.whatiuse-donut-chart__content {
    grid-template-columns: minmax(148px, .82fr) minmax(150px, 1.18fr);
    gap: 12px;
    min-height: 218px;
    padding: 11px;
    border-radius: 9px;
    background: var(--whatiuse-bg-surface);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--whatiuse-control-border) 58%, transparent), 0 1px 2px rgb(17 17 19 / .025);
  }

.whatiuse-donut-chart__stage { min-height: 218px; }

.whatiuse-donut-chart__stage > .whatiuse-chart__table { height: 218px; }

.whatiuse-donut-chart__plot { max-width: 184px; }

.whatiuse-donut-chart__track,
.whatiuse-donut-chart__segment { stroke-width: 15; }

.whatiuse-donut-chart__center strong { font-size: 19px; }

.whatiuse-donut-chart__legend button {
    min-height: 34px;
    grid-template-columns: 7px minmax(0, 1fr) auto;
    gap: 7px;
    padding: 4px 6px;
  }

.whatiuse-donut-chart__legend button small { display: none; }

@media (max-width: 640px) {
.whatiuse-donut-chart__content { grid-template-columns: 1fr; }

.whatiuse-donut-chart__plot { max-width: 176px; }
}

@keyframes whatiuse-spin { to { transform: rotate(360deg); } }
}
